/* Struct Layouts */
struct Any {
    const char* _type_name;
    void** _vtable;
};

struct Loadable {
    const char* _type_name;
    void** _vtable;
};

struct Stringable {
    const char* _type_name;
    void** _vtable;
};

struct Class {
    const char* _type_name;
    void** _vtable;
};

